export interface Pair {
  first: number;
  second: number;
}

export function makePair(first: number, second: number): Pair {
  return { first, second };
}

export const origin: string = "the sources";

// The built files do not have it yet.
export function swap(pair: Pair): Pair {
  return { first: pair.second, second: pair.first };
}
